class User {
  + username : string
  + password : string
}

class Player extends User {
  + lives : int
}

class Admin extends User {
}

class Game {
  + name : string
  + minSpeed : float
  + speedIncreaseFactor : float
  + maxPaddleLength : float
  + minPaddleLength : float
}

class HallOfFame {
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
}

class GridPosition {
  + x : int
  + y : int
}

class BlockPlacement {
}

class GameSession {
  + currentScore : int
  + currentLives : int
}

Admin "0..1" -- "*" Game : manages
Player "0..*" -- "*" Game : plays
Game "1" *-- "1" HallOfFame
Game "1" *-- "*" Level
Game "1" *-- "*" Block
Level "1" *-- "*" BlockPlacement
BlockPlacement "*" -- "1" Block
BlockPlacement "*" -- "1" GridPosition
Game "1" *-- "0..*" GameSession

@enduml

